@Test
void shouldPositionPerUserHeaders() throws Exception {
    RspamdHttpClient rspamdHttpClient = mock(RspamdHttpClient.class);
    RspamdClientConfiguration configuration = mock(RspamdClientConfiguration.class);
    when(configuration.usePerUserBayes()).thenReturn(true);
    when(rspamdHttpClient.checkV2(any(Mail.class), eq(RspamdHttpClient.Options.forUser(Username.of("user1@exemple.com"))))).thenReturn(Mono.just(AnalysisResult.builder().action(AnalysisResult.Action.NO_ACTION).score(1.1F).requiredScore(14F).build()));
    when(rspamdHttpClient.checkV2(any(Mail.class), eq(RspamdHttpClient.Options.forUser(Username.of("user2@exemple.com"))))).thenReturn(Mono.just(AnalysisResult.builder().action(AnalysisResult.Action.ADD_HEADER).score(12.1F).requiredScore(14F).build()));
    mailet = new RspamdScanner(rspamdHttpClient, configuration);
    mailet.init(FakeMailetConfig.builder().setProperty("virusProcessor", "virus").setProperty("rejectSpamProcessor", "spam").build());
    Mail mail = FakeMail.builder().name("name").recipients("user1@exemple.com", "user2@exemple.com").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().addToRecipient("user1@exemple.com").addFrom("sender@exemple.com").setSubject(INIT_SUBJECT).setText("Please!").build()).build();
    mailet.service(mail);
    Collection<PerRecipientHeaders.Header> headersForRecipient1 = mail.getPerRecipientSpecificHeaders().getHeadersForRecipient(new MailAddress("user1@exemple.com"));
    assertThat(headersForRecipient1.stream().filter(header -> header.getName().equals(RspamdScanner.FLAG_MAIL.asString())).filter(header -> header.getValue().startsWith("NO")).findAny()).isPresent();
    Collection<PerRecipientHeaders.Header> headersForRecipient2 = mail.getPerRecipientSpecificHeaders().getHeadersForRecipient(new MailAddress("user2@exemple.com"));
    assertThat(headersForRecipient2.stream().filter(header -> header.getName().equals(RspamdScanner.FLAG_MAIL.asString())).filter(header -> header.getValue().startsWith("YES")).findAny()).isPresent();
}

