public void doneShouldCopyMailFromOutboxToSentOnlyOneTimeWhenSuccess() throws Exception {
    MessageIdManager messageIdManager = mock(MessageIdManager.class);
    testee = new PostDequeueDecorator(mockedMailQueueItem, mailboxManager, new InMemoryMessageId.Factory(), messageIdManager, new SystemMailboxesProviderImpl(mailboxManager));
    MailboxSession mailboxSession = mailboxManager.createSystemSession(USERNAME);
