void otherAttachmentsShouldBeenIndexedWhenOneOfThemCannotBeParsed() throws Exception {
    //Given
    MailboxMessage mailboxMessage = mock(MailboxMessage.class);
    TestId mailboxId = TestId.of(1);
    when(mailboxMessage.getMailboxId()).thenReturn(mailboxId);
    when(mailboxMessage.getModSeq()).thenReturn(ModSeq.first());
    when(mailboxMessage.getMessageId()).thenReturn(InMemoryMessageId.of(42));
    when(mailboxMessage.getFullContent()).thenReturn(ClassLoader.getSystemResourceAsStream("eml/emailWith3Attachments.eml"));
    when(mailboxMessage.createFlags()).thenReturn(new Flags());
    when(mailboxMessage.getUid()).thenReturn(MESSAGE_UID);
    TextExtractor textExtractor = mock(TextExtractor.class);
    when(textExtractor.applicable(any())).thenReturn(true);
    when(textExtractor.extractContentReactive(any(), any())).thenReturn(Mono.just(ParsedContent.of("first attachment content"))).thenReturn(Mono.error(new RuntimeException("second cannot be parsed"))).thenReturn(Mono.just(ParsedContent.of("third attachment content")));
    // When
    IndexableMessage indexableMessage = IndexableMessage.builder().message(mailboxMessage).extractor(textExtractor).zoneId(ZoneId.of("Europe/Paris")).indexAttachments(IndexAttachments.YES).indexHeaders(IndexHeaders.YES).build().block();
    // Then
    String noTextualBody = "The textual body is not present";
    assertThat(indexableMessage.getAttachments()).extracting(input -> input.bodyTextContent().orElse(noTextualBody)).contains("first attachment content", noTextualBody, "third attachment content");
}

