    when(invalidMessageIdThatReturnNull.serialize()).thenReturn(null);
    // When
    MailboxMessage mailboxMessage = mock(MailboxMessage.class);
    TestId mailboxId = TestId.of(1);
    when(mailboxMessage.getMailboxId()).thenReturn(mailboxId);
    when(mailboxMessage.getModSeq()).thenReturn(ModSeq.first());
    when(mailboxMessage.getMessageId()).thenReturn(invalidMessageIdThatReturnNull);
    when(mailboxMessage.getFullContent()).thenReturn(ClassLoader.getSystemResourceAsStream("eml/bodyMakeTikaToFail.eml"));
    when(mailboxMessage.createFlags()).thenReturn(new Flags());
    when(mailboxMessage.getUid()).thenReturn(MESSAGE_UID);
    IndexableMessage indexableMessage = IndexableMessage.builder().message(mailboxMessage).extractor(textExtractor).zoneId(ZoneId.of("Europe/Paris")).indexAttachments(IndexAttachments.YES).indexHeaders(IndexHeaders.YES).build().block();
    // Then
    assertThat(indexableMessage.getMessageId()).isNull();
}

